#JellyRollBlues by Jelly Roll Morton, 1924 arranged for Sonic Pi by Robin Newman, Jan 2017
#requires SP 2.11 or later so that it can be played using run_file "path/to/file/JellyRollBlues-RF.rb"
#the Right and Left hand parts are each split into three, to accommodate the notes
#whilst still allowing the script to work to convert from the original MusicXML files
#to Sonic Pi format. 
s=1;r=0.1 #sustain release parameters
with_fx :reverb,room: 0.8 do
use_synth :piano
with_fx :level do |v| #produce accents (at the end of the trills)
in_thread do
ff=1.4;n=0.8 #accent and normal levels
use_bpm 140
control v,amp: n
sleep 28*4
control v,amp: ff
sleep 0.5
control v,amp: n
sleep 3.5
control v,amp: ff
sleep 0.5
control v,amp: n
sleep 3.5
control v,amp: ff
sleep 0.5
control v,amp: n
sleep 10*4-0.5
control v,amp: ff
sleep 0.5
control v,amp: n
sleep 3.5
control v,amp: ff
sleep 0.5
control v,amp: n
sleep 3.5
control v,amp: ff
sleep 0.5
control v,amp: n
end
with_synth_defaults hard: 0.45,stereo_width: 0.5,velociy: 0.18  do #adjust piano parameters
with_fx :level,amp: 1.2 do #rh level (relative)
